  "Bauteil gefunden! An Werkbank und Schmiede wird daraus ein Meisterwerk.": "Part found! Turn parts into a Masterwork at the Workbench or the Forge.",
  "VERBESSERN": "IMPROVE",
  "SCHMIEDEN": "FORGE",
