  "Begleiter-Ausrüstung: {n} ({r})": "Companion gear: {n} ({r})",
  "BEGLEITER-EI!": "EGG FOUND!",
  "{egg}! Bring es ins Brutnest im Versteck.": "{egg}! Take it to the Hatchery in your Hideout.",
  "Ein Begleiter-Ei! Dein Brutnest ist voll – dafür +1 Glücksmünze.": "A companion egg! Your nest is full – so you get +1 Fortune Coin instead.",
  "SCHILD": "SHIELD",
  "Nestmutter Gunda": "Nest Mother Gunda",
  "Wärme, Futter, Zuwendung. Fehlt eins davon, schläft das Küken im Ei einfach weiter.": "Warmth, food, affection. If one is missing, the chick inside just keeps on sleeping.",
  "Sind alle drei Bedürfnisse gut gefüllt, wächst ein Ei anderthalbmal so schnell.": "When all three needs are well filled, an egg grows one and a half times as fast.",
  "Streichle die Eier ruhig. Die spüren das. Wirklich.": "Go ahead, pet the eggs. They can feel it. Really.",
  "Aus einem schmutzigen Ei schlüpft meist eine Schnecke. Aber man liebt sie trotzdem.": "A grubby egg usually hatches a snail. But you love it anyway.",
  "Ein mythisches Ei braucht Tage. Und Sternenstaub. Und Geduld. Vor allem Geduld.": "A mythic egg takes days. And stardust. And patience. Mostly patience.",
  "Brutnest: Ein Ei ist bereit zum Schlüpfen!": "Hatchery: an egg is ready to hatch!",
  "Brutnest: {n} Eier sind bereit zum Schlüpfen!": "Hatchery: {n} eggs are ready to hatch!",
  "Brutnest: Ein Ei braucht dich – es wächst gerade nicht.": "Hatchery: an egg needs you – it isn't growing right now.",
  "Brutnest: {n} Eier brauchen dich – sie wachsen gerade nicht.": "Hatchery: {n} eggs need you – they aren't growing right now.",
  "BEREIT": "READY",
  "Ein Ei! Das hast du dem Boss abgenommen? Bring es zu mir ins Brutnest – ich wohne jetzt im Versteck.": "An egg! You took that from the boss? Bring it to me at the Hatchery – I live in the Hideout now.",
  "Ein Ei! Wo hast du das denn gefunden? Bring es zu mir ins Brutnest – ich wohne jetzt im Versteck.": "An egg! Where did you find that? Bring it to me at the Hatchery – I live in the Hideout now.",
  "Halt es warm, füttere es und schenk ihm Zuwendung. Dann wächst es – auch während du unterwegs bist.": "Keep it warm, feed it and give it some affection. Then it grows – even while you're out adventuring.",
  "Irgendwann schlüpft daraus dein erster Begleiter. Komm, ich zeig dir das Nest.": "Someday your first companion will hatch from it. Come, I'll show you the nest.",
  "Ich bin Gunda und kümmere mich ab jetzt um das Brutnest im Versteck.": "I'm Gunda, and from now on I'll look after the Hatchery in the Hideout.",
  "Eier schlüpfen nicht mehr von allein: Halt sie warm, füttere sie und schenk ihnen Zuwendung. Dann wachsen sie, auch während du unterwegs bist.": "Eggs don't hatch on their own anymore: keep them warm, feed them and give them some affection. Then they grow, even while you're out adventuring.",
  "DEIN ERSTES EI": "YOUR FIRST EGG",
  "NEU: DAS BRUTNEST": "NEW: THE HATCHERY",
