  "Fällst du in den Verlorenen Landen, rettet dein Begleiter, was in seinem Beutel liegt. Seltenere Arten tragen mehr, das Talent „Große Taschen“ gibt weitere Plätze.": "If you fall in the Lost Lands, your companion saves whatever is in its bag. Rarer species carry more, and the “Big Pockets” talent adds more slots.",
