  "Man sagt, {name} habe einst {deed}.": "They say {name} once {deed}.",
  "Seit {n} Wintern haust {name} in {place}.": "For {n} winters, {name} has lurked in {place}.",
  "{name} sammelt {thing} – und die Knochen derer, die danach fragen.": "{name} collects {thing} – and the bones of those who come asking.",
  "Wer {name} begegnet, hört zuerst {sound}.": "Whoever meets {name} first hears {sound}.",
  "Die Kundschafter meiden {place}, seit {name} dort erwacht ist.": "Scouts have shunned {place} ever since {name} awoke there.",
  "{name} fürchtet nur eines: {fear}.": "{name} fears only one thing: {fear}.",
  "Alte Lieder erzählen, {name} sei aus {origin} geboren.": "Old songs tell that {name} was born of {origin}.",
  "Auf {name} steht ein Kopfgeld von {g} Gold. Niemand hat es je abgeholt.": "There's a bounty of {g} gold on {name}. No one has ever claimed it.",
  "Die Karten des Ordens nennen {place} nur „das Revier von {name}“.": "The Order's maps call {place} only “the hunting ground of {name}”.",
  "{name} spricht nie. Doch in {place} flüstern die Steine diesen Namen.": "{name} never speaks. But in {place}, the stones whisper that name.",
  "ein ganzes Heer in Stein verwandelt": "turned an entire army to stone",
