  "Heiltotem": "Healing Totem",
  "Ein eisiger Ring um den Boss friert ein, wer drinsteht. Raus aus dem Kreis!": "An icy ring around the boss freezes anyone standing inside. Get out of the circle!",
  "Meteorregen": "Meteor Shower",
  "Brennende Felsen fallen vom Himmel. Die Kreise zeigen, wo sie einschlagen.": "Burning rocks fall from the sky. The circles show where they'll hit.",
  "Schockwellen": "Shockwaves",
  "Der Boss stampft – Wellen rollen nach außen. Rolle durch die Welle oder bleib außer Reichweite.": "The boss stomps – waves roll outward. Roll through the wave or stay out of range.",
  "Tipp: Während du rollst, kann dich nichts treffen – rolle durch Wellen hindurch!": "Tip: Nothing can hit you while you roll – roll right through the waves!",
  "Eine Bahn zeigt, wohin der Boss gleich stürmt. Geh zur Seite!": "A lane shows where the boss is about to charge. Step aside!",
  "Beschwörung": "Summoning",
  "Aus Portalen kriechen Diener. Erledige sie, bevor es zu viele werden.": "Minions crawl out of portals. Take them out before there are too many.",
  "Schutzschild": "Shield",
  "Ein Schild schluckt viel Schaden. Brich ihn – dann ist der Boss kurz benommen.": "A shield soaks up lots of damage. Break it – and the boss is stunned for a moment.",
  "Tipp: Brich den Schild – dann ist der Boss ein paar Sekunden benommen.": "Tip: Break the shield – and the boss is stunned for a few seconds.",
  "Der Boss verschwindet und taucht am markierten Ort wieder auf – mit einem Schlag.": "The boss vanishes and reappears at the marked spot – with a strike.",
  "Giftwolken": "Poison Clouds",
  "Giftblasen platzen und hinterlassen Wolken, die lange brennen.": "Poison bubbles burst and leave clouds that burn for a long time.",
  "Blitzschlag": "Lightning Strike",
  "Ein Zeichen folgt dir und bleibt dann stehen – lauf weg, bevor der Blitz einschlägt.": "A mark follows you and then stops – run before the lightning strikes.",
  "Tipp: Das Zeichen folgt dir – sobald es stehen bleibt, lauf weg!": "Tip: The mark follows you – as soon as it stops, run!",
  "Atemstoß": "Breath Blast",
  "Ein Fächer vor dem Boss wird gleich in Feuer, Eis oder Gift getaucht. Geh hinter ihn oder zur Seite.": "A cone in front of the boss is about to be engulfed in fire, ice or poison. Get behind it or to the side.",
  "Todessprung": "Death Leap",
  "Der Boss springt dorthin, wo du stehst. Der Schatten am Boden zeigt die Landung.": "The boss leaps to where you're standing. The shadow on the ground shows the landing.",
  "Kugelring": "Orb Ring",
  "Ein Ring aus Geschossen fliegt nach außen. Stell dich in eine Lücke.": "A ring of projectiles flies outward. Stand in a gap.",
  "Kreuzschnitt": "Cross Cut",
  "Leuchtende Linien durch den Boss werden gleich zu Klingen. Weg von den Linien!": "Glowing lines through the boss are about to become blades. Get off the lines!",
  "Erdspalten": "Earth Rifts",
  "Der Boden reißt vom Boss in deine Richtung auf. Geh aus der Spur.": "The ground tears open from the boss toward you. Get out of its path.",
  "Klingenwirbel": "Blade Vortex",
  "Klingen kreisen um den Boss. Erst sind sie blass – dann schneiden sie.": "Blades circle the boss. At first they're faint – then they cut.",
  "Ein ganzes Feld fängt Feuer. Verlass die markierte Fläche schnell.": "A whole area catches fire. Leave the marked zone fast.",
  "Lebensraub": "Life Drain",
  "Im Kreis um den Boss saugt er dir Leben aus und heilt sich. Verlass den Kreis.": "Inside the circle around the boss, it drains your life and heals itself. Leave the circle.",
  "Tipp: Verlass den roten Kreis, dann reißt der Lebensraub ab.": "Tip: Leave the red circle and the Life Drain breaks off.",
  "Unter 30 % Leben wird der Boss schneller und stärker.": "Below 30% health, the boss gets faster and stronger.",
  "Phasen": "Phases",
  "Bei 66 % und 33 % Leben stößt der Boss alle zurück und kämpft danach schneller – manchmal mit neuen Kräften.": "At 66% and 33% health, the boss knocks everyone back and fights faster afterwards – sometimes with new powers.",
  "Seelenjäger": "Soul Hunters",
  "Langsame Geister verfolgen dich. Weiche aus oder zerschlag sie mit Nahkampfhieben.": "Slow spirits chase you. Dodge them or smash them with melee hits.",
  "Sprengsaat": "Blast Seeds",
  "Der Boss verstreut Minen. Kommst du zu nah, zünden sie – der rote Kreis zeigt die Explosion.": "The boss scatters mines. Get too close and they go off – the red circle shows the blast.",
  "Der Boss heilt sich. Viel Schaden in kurzer Zeit unterbricht ihn.": "The boss heals itself. Lots of damage in a short time interrupts it.",
  "Tipp: Viel Schaden in kurzer Zeit unterbricht die Heilung.": "Tip: Lots of damage in a short time interrupts the healing.",
  "Heiltotems": "Healing Totems",
  "Totems heilen den Boss, solange sie stehen. Zerstöre sie zuerst.": "Totems heal the boss as long as they stand. Destroy them first.",
  "Tipp: Die Totems heilen den Boss – zerstöre sie zuerst!": "Tip: The totems heal the boss – destroy them first!",
  "Sog": "Pull",
  "Der Boss zieht dich zu sich – in seiner Mitte wartet Schaden. Lauf dagegen an.": "The boss pulls you in – damage awaits at its center. Run against the pull.",
  "Kugelspirale": "Orb Spiral",
  "Drehende Arme aus Geschossen. Bewege dich mit der Drehung.": "Spinning arms of projectiles. Move with the rotation.",
  "Blitze springen zwischen Punkten um dich herum. Stell dich nicht auf eine Linie.": "Lightning jumps between points around you. Don't stand on a line.",
  "Spiegelbilder": "Mirror Images",
  "Trugbilder des Bosses erscheinen. Nur der echte leuchtet und hat den Lebensbalken oben.": "Illusions of the boss appear. Only the real one glows and has the health bar at the top.",
  "Tipp: Nur der echte Boss hat den leuchtenden Rand – die Trugbilder zerfallen schnell.": "Tip: Only the real boss has the glowing outline – the illusions fade quickly.",
  "Todesstrahl": "Death Ray",
  "Eine dünne Linie zeigt den Strahl an – dann dreht er sich durch die Arena. Bleib hinter ihm.": "A thin line marks the beam – then it sweeps through the arena. Stay behind it.",
  "Finsternis": "Darkness",
  "Alle Lichter erlöschen für ein paar Sekunden. Gefahren leuchten trotzdem.": "All lights go out for a few seconds. Dangers still glow.",
  "Tipp: Farbige Flächen zeigen, wo gleich Schaden kommt. Raus da, bevor sie aufleuchten!": "Tip: Colored areas show where damage is about to hit. Get out before they light up!",
