  "Extrahiert: {ess}": "Extracted: {ess}",
  "{n}× kombiniert – bestes: {mod}": "Combined {n}× – best: {mod}",
  "1 Mod zurück in den Vorrat": "1 mod back to your supplies",
  "Seil": "Rope",
  "Ein Kletterseil mit Wurfhaken – damit kommst du an den Übergängen über Schluchten.": "A climbing rope with a grappling hook – it gets you across chasms at the crossings.",
  "Brückenstein": "Bridgestone",
  "Ein Stein der Alten: Er lässt eingestürzte Brücken über reißende Flüsse wieder erstehen.": "A stone of the Ancients: it raises collapsed bridges over raging rivers once more.",
  "Kräutermaske": "Herb Mask",
  "Filtert Giftnebel und Giftluft. Ohne sie brennt jeder Atemzug.": "Filters toxic fog and toxic air. Without it, every breath burns.",
  "Eishaken": "Ice Hook",
  "Steigeisen und Haken: Damit erklimmst du Eisklippen an den markierten Stellen.": "Crampons and hooks: with them, you can scale ice cliffs at the marked spots.",
  "Feuermantel": "Fire Cloak",
  "Schützt vor Lava, Hitze und eisiger Kälte. Über Lavaströme führen Trittsteine.": "Protects against lava, heat and freezing cold. Stepping stones lead across lava flows.",
  "Schattenlaterne": "Shadow Lantern",
  "Ihr Licht durchdringt die lebendige Finsternis und vertreibt die Dunkelheit.": "Its light pierces the living darkness and drives away the gloom.",
  "Gezeitenperle": "Tide Pearl",
  "Teilt die Fluten: An den Pfeilern der Alten trägt dich das Wasser.": "Parts the floods: at the pillars of the Ancients, the water carries you.",
  "Dornenklinge": "Thorn Blade",
  "Schneidet Wege durch Dornenwälle, die nichts anderes durchdringt.": "Cuts paths through thorn walls that nothing else can pierce.",
  "Sturmfeder": "Storm Feather",
  "Hält dich im Auge des Sturms – Sturmwände und Böen werfen dich nicht mehr zurück.": "Keeps you in the eye of the storm – storm walls and gusts no longer throw you back.",
  "Sternenschlüssel": "Star Key",
  "Öffnet die uralten Siegel der Sternentore.": "Opens the ancient seals of the star gates.",
  "Leere-Anker": "Void Anchor",
  "Verankert dich in der Wirklichkeit – über Leere-Risse und durch das Nichts.": "Anchors you in reality – across void rifts and through the nothingness.",
  "Seil II": "Rope II",
  "Ein Seil aus Sternenfaden mit Kristallhaken – es hält auch über der Kristallkluft, wo jedes andere Seil zerschneidet.": "A rope of star thread with crystal hooks – it holds even over the Crystal Chasm, where any other rope gets sliced apart.",
  "Kräutermaske II": "Herb Mask II",
  "Gefüllt mit Kräutern vom Rand der Welt: Sie filtert die Wand aus Blutnebel, den Blutdunst der Sümpfe und die Sporenluft der Pilzriesen.": "Filled with herbs from the edge of the world: it filters the wall of Blood Fog, the Blood Haze of the swamps and the Spore Clouds of the Mushroom Giants.",
  "Eishaken II": "Ice Hook II",
  "Haken aus Himmelsstahl: Damit kletterst du am Himmelsabbruch entlang, und kein Höhensturm reißt dich fort.": "Hooks of sky steel: with them you climb along the Sky Precipice, and no Sky Gale can sweep you away.",
  "Brückenstein II": "Bridgestone II",
  "Ein Stein der Alten, der Brücken über den Seelenstrom baut. Sein Licht hält auch den Seelensog von dir fern.": "A stone of the Ancients that builds bridges across the Soul Torrent. Its light also keeps the Soul Drain away from you.",
  "Feuermantel II": "Fire Cloak II",
  "Gewebt aus Sternenfeuer: schützt vor Sternenglut und Grabeskälte. Über die Glutströme führen schwebende Steine.": "Woven from starfire: protects against Starblaze and Grave Chill. Floating stones lead across the ember flows.",
  "Schattenlaterne II": "Shadow Lantern II",
  "Ihr Licht weckt dich aus jedem Traum: Sie zerreißt den Traumschleier und vertreibt den Traumnebel.": "Its light wakes you from any dream: it tears through the Dream Veil and drives away the Dream Mist.",
  "Gezeitenperle II": "Tide Pearl II",
  "Eine Perle aus erstarrter Zeit: An den Stundenpfeilern hält sie den Zeitstrom an und schützt vor dem Zeitsog.": "A pearl of frozen time: at the hour pillars it halts the Timestream and shields you from Time Drag.",
  "Dornenklinge II": "Thorn Blade II",
  "Geschmiedet aus Sternensplittern: Sie schneidet Wege durch Splitterwälle und zerschlägt den Splitterregen.": "Forged from star shards: it cuts paths through Shard Walls and smashes the Shard Rain.",
  "Sternenschlüssel II": "Star Key II",
  "Der Schlüssel zum Siegel der Welt. Dahinter liegt nur noch der Weltenrand – und das Ende der Welt.": "The key to the World Seal. Beyond it lies only the World's Edge – and World's End.",
