  "Splitterwall": "Shard Wall",
  "Siegel der Welt": "World Seal",
  "Giftluft": "Toxic Air",
  "Giftluft! Ohne Kräutermaske brennt jeder Atemzug.": "Toxic air! Without a Herb Mask, every breath burns.",
  "Eisige Kälte": "Freezing Cold",
  "Eisige Kälte! Ohne Feuermantel wirst du langsam und frierst.": "Freezing cold! Without a Fire Cloak, you slow down and freeze.",
  "Glühende Hitze": "Searing Heat",
  "Glühende Hitze! Ohne Feuermantel versengt sie dich.": "Searing heat! Without a Fire Cloak, it scorches you.",
  "Finsternis! Ohne Schattenlaterne siehst du kaum die Hand vor Augen.": "Darkness! Without a Shadow Lantern, you can barely see your hand in front of your face.",
  "Sturm": "Storm",
  "Sturm! Ohne Sturmfeder werfen dich die Böen umher.": "Storm! Without a Storm Feather, the gusts toss you around.",
  "Sog der Leere": "Void Pull",
  "Die Leere saugt an deiner Kraft! Ohne Leere-Anker schwindet sie.": "The Void drains your strength! Without a Void Anchor, it fades away.",
  "Blutdunst": "Blood Haze",
  "Blutdunst! Ohne Kräutermaske II saugt er dir das Leben aus.": "Blood haze! Without Herb Mask II, it sucks the life out of you.",
  "Sporenluft": "Spore Cloud",
  "Sporenluft! Ohne Kräutermaske II vergiftet sie dich.": "Spore cloud! Without Herb Mask II, it poisons you.",
  "Höhensturm": "Sky Gale",
  "Höhensturm! Ohne Eishaken II reißt er dich von den Füßen.": "Sky gale! Without Ice Hook II, it sweeps you off your feet.",
  "Seelensog": "Soul Drain",
  "Seelensog! Ohne Brückenstein II zehren die Seelen an Kraft und Leben.": "Soul drain! Without Bridgestone II, the souls gnaw at your strength and life.",
  "Sternenglut! Ohne Feuermantel II verbrennst du.": "Starblaze! Without Fire Cloak II, you burn.",
  "Grabeskälte": "Grave Chill",
  "Grabeskälte! Ohne Feuermantel II erstarrst du.": "Grave chill! Without Fire Cloak II, you freeze stiff.",
  "Traumnebel": "Dream Mist",
  "Traumnebel! Ohne Schattenlaterne II wirst du müde und siehst kaum etwas.": "Dream mist! Without Shadow Lantern II, you grow drowsy and can barely see.",
  "Zeitsog": "Time Drag",
  "Zeitsog! Ohne Gezeitenperle II zerrt die Zeit an dir.": "Time drag! Without Tide Pearl II, time tugs at you.",
  "Splitterregen": "Shard Rain",
  "Splitterregen! Ohne Dornenklinge II schneiden dich die Splitter.": "Shard rain! Without Thorn Blade II, the shards cut you.",
