  "DIE NACHT BRICHT AN": "NIGHT FALLS",
  "Jäger der Nacht sind unterwegs. Halte ein Tor oder Leuchtfeuer im Blick!": "Night Hunters are on the prowl. Keep a gate or beacon in sight!",
