  "UNGEHEUER BEZWUNGEN": "MONSTER SLAIN",
  "Schnapp dir die Beute – und dann nichts wie raus!": "Grab the loot – and then get out of here!",
  "RIVALE BESIEGT": "RIVAL DEFEATED",
  "{name} lässt alles fallen, was er gesammelt hat.": "{name} drops everything they collected.",
