  "+{n} frei": "+{n} free",
  "Tippe etwas an: anlegen, in die Begleiter-Tasche legen oder wegwerfen.": "Tap an item: equip it, put it in the companion pouch or drop it.",
  "Alle {n} in die Begleiter-Tasche": "All {n} to Companion Pouch",
