  "{name} bringt das heim – auch wenn du fällst.": "{name} brings this home – even if you fall.",
  "Keine Plätze.": "No slots.",
  "Kein Begleiter dabei: Stirbst du, ist alles verloren.": "No companion with you: if you die, everything is lost.",
  "Ohne Begleiter-Tasche: Stirbst du, ist alles verloren.": "No companion pouch: if you die, everything is lost.",
