  "ohne Platzgrenze · {n} G": "no slot limit · {n} G",
  "Gold, Material, Edelsteine, Bauteile und Mods landen hier – sie brauchen keinen Platz im Rucksack.": "Gold, materials, gems, parts and mods land here – they take up no space in your backpack.",
