  "{n} Dinge weggeworfen": "{n} items dropped",
  "Ein Rückweg öffnet sich unter deinen Füßen – bleib stehen!": "A way back opens beneath your feet – stand still!",
  "MITTEN IM KAMPF!": "IN COMBAT!",
  "Abbrechen geht nur, wenn dich gerade nichts angreift. Lauf weg oder kämpfe!": "You can only abandon when nothing is attacking you. Run away or fight!",
  "AUSFLUG ABBRECHEN?": "ABANDON RUN?",
  "Rucksack und Sammelbeutel bleiben in den Landen, und was du seit dem letzten Leuchtfeuer erkundet hast, ist vergessen. Du behältst die Ausrüstung, mit der du aufgebrochen bist, alles in der Begleiter-Tasche und was Vögel schon heimgebracht haben.": "Your backpack and gathering pouch stay in the Lands, and whatever you've explored since the last beacon is forgotten. You keep the gear you set out with, everything in the companion pouch and whatever birds have already brought home.",
  "Ja, abbrechen": "Yes, abandon",
  "Weiter erkunden": "Keep exploring",
  "Ausflug abgebrochen – {n} Dinge sind verloren.": "Run abandoned – {n} items lost.",
  "Ausflug abgebrochen.": "Run abandoned.",
  "Du hast keinen Leuchtfeuerstein. Sie liegen selten in Truhen, bei Bossen und bei Händlern.": "You don't have a beacon stone. They're rarely found in chests, on bosses and at merchants.",
  "Nicht mitten im Kampf!": "Not in the middle of a fight!",
  "Hier ist kein fester Boden.": "There's no solid ground here.",
  "Zu nah an einem Ausgang, Lager oder Leuchtfeuer.": "Too close to an exit, camp or beacon.",
  "LEUCHTFEUER SETZEN": "SET BEACON",
  "{n} STEINE": "{n} STONES",
  "Ein Leuchtfeuer kostet einen Leuchtfeuerstein und brennt für immer.": "A beacon costs one beacon stone and burns forever.",
  "Die Karte bis hierher wird gesichert – auch wenn du später fällst.": "Your map up to this point is saved – even if you fall later.",
  "Beim nächsten Ausflug kannst du hier starten.": "You can start here on your next run.",
  "Es ist ein Ausgang: hineinstellen und warten – die Beute ist sicher.": "It's an exit: step inside and wait – your loot is safe.",
  "{d} vom Weltentor": "{d} from the World Gate",
  "Du hast schon {n} Leuchtfeuer – das am längsten unbenutzte erlischt: {name}": "You already have {n} beacons – the one unused the longest goes out: {name}",
  "Leuchtfeuer: {n} von {max}": "Beacons: {n} of {max}",
  "Entzünden (1 Leuchtfeuerstein)": "Light (1 beacon stone)",
  "LEUCHTFEUER ENTZÜNDET": "BEACON LIT",
  "Karte gesichert ({n} neue Regionen). Hier startest du beim nächsten Mal – und hier kommst du raus.": "Map saved ({n} new regions). You'll start here next time – and this is your way out.",
  "Leuchtfeuer / Ausgang": "Beacon / Exit",
