  "Kundschafterinnen in den Außenposten haben Aufträge für dich.": "Scouts in the outposts have missions for you.",
  "AUFTRÄGE": "MISSIONS",
  "Belohnung: {rep} Ruf, {items}": "Reward: {rep} rep, {items}",
  "Schlüssel": "Key",
  "Belohnung nehmen": "Claim reward",
  "Gerücht über eine Spur": "Rumor of a trail",
  "Tipp: Erfüllte Aufträge zahlen hier – oder automatisch, wenn du lebend durch einen Ausgang gehst.": "Tip: Completed missions pay out here – or automatically when you make it out alive through an exit.",
  "Gerücht: {tool}": "Rumor: {tool}",
  "Ein Hort mit diesem Werkzeug soll etwa {d} im {dir} liegen. Auf der Karte ist die Gegend markiert.": "A hoard with this tool is said to lie about {d} to the {dir}. The area is marked on your map.",
  "„Der Orden braucht Augen hier draußen. Erledige, was du kannst – bezahlt wird, wenn du es mir bringst oder lebend durch ein Tor gehst.“": "“The Order needs eyes out here. Do what you can – you get paid when you bring it to me or make it through a gate alive.”",
  "RUF: {n}": "REP: {n}",
  "Nächster Rang: {n} – {d}": "Next rank: {n} – {d}",
  "+{n} Ruf bei den Kundschaftern": "+{n} rep with the Scouts",
  "Gib:": "Give:",
  "Heiltrank": "Health Potion",
  "Kartenstück": "Map Fragment",
  "Rückkehrrolle (Ausgang überall, doppelt so lange stehen)": "Return Scroll (exit anywhere, stand twice as long)",
  "Leuchtfeuerstein (einer je Außenposten)": "Beacon stone (one per outpost)",
  "Bezahlt wird mit dem Gold in deinem Rucksack.": "You pay with the gold in your backpack.",
  "Leuchtfeuersteine verkaufen Händler erst ab dem Ruf „Bekannter“.": "Merchants only sell beacon stones once your standing reaches “Acquaintance”.",
  "Das Gold kommt in den Sammelbeutel – raustragen musst du es trotzdem.": "The gold goes into your gathering pouch – but you still have to carry it out.",
  "Dein Rucksack ist leer.": "Your backpack is empty.",
  "„Hier draußen zahlt man mit dem, was man trägt. Zeig her, was du hast.“": "“Out here, you pay with what you carry. Show me what you've got.”",
  "TAUSCH": "TRADE",
  "KAUFEN": "BUY",
