  "{bird} gekauft – im Rucksack unter „Vogel schicken“": "{bird} bought – find it in your backpack under “Send Bird”",
  "„Setz dich ans Feuer. Die Lande nehmen viel – ein bisschen gebe ich zurück.“": "“Sit by the fire. The Lands take a lot – I give a little back.”",
  "LP {hp}/{max} · Tränke {n}/{m}": "HP {hp}/{max} · Potions {n}/{m}",
