  "Alles abholen": "Claim all",
  "WERKZEUGE {n}/{max}": "TOOLS {n}/{max}",
  "Als Nächstes: {tool} – für {bar} etwa {d} vom Tor. Horte damit liegen diesseits davon.": "Next up: {tool} – for the {bar} about {d} from the gate. Hoards holding it lie on this side of it.",
  "Du hast alle Werkzeuge. Die ganze Welt steht dir offen – bis an ihren Rand.": "You have every tool. The whole world is open to you – all the way to its edge.",
  "STARTPUNKT": "START FROM",
  "LEUCHTFEUERSTEINE {n}": "BEACON STONES {n}",
  "LEUCHTFEUER {n}/{max}": "BEACONS {n}/{max}",
  "SCHLÜSSEL {n}": "KEYS {n}",
  "Karte der Lande": "Map of the Lands",
  "WAS DU RISKIERST · {n} GOLD": "WHAT YOU RISK · {n} GOLD",
  "WAS ÜBERLEBT": "WHAT SURVIVES",
  "Stirbst du, sind Ausrüstung, Rucksack und Sammelbeutel verloren.": "If you die, your gear, backpack and gathering pouch are lost.",
  "Nur die Begleiter-Tasche kommt heim – dein Begleiter teleportiert mit dir zurück.": "Only the companion pouch comes home – your companion teleports back with you.",
  "Gold, Material und Edelsteine landen im Sammelbeutel – ohne Platzgrenze. Magische Vögel bringen Beute schon unterwegs heim (dabei: {n}).": "Gold, materials and gems land in your gathering pouch – no slot limit. Magical birds carry loot home while you're still out there (with you: {n}).",
  "Raus kommst du durch ein Tor der Alten, das Weltentor oder ein Leuchtfeuer: hineinstellen und warten.": "You get out through a Gate of the Ancients, the World Gate or a beacon: step inside and wait.",
  "Die Karte wird nur gesichert, wenn du ein Leuchtfeuer setzt oder entkommst – wer fällt, vergisst den Weg seit dem letzten Leuchtfeuer.": "Your map is only saved when you set a beacon or escape – if you fall, you forget the way since your last beacon.",
  "Abbrechen geht nur außerhalb des Kampfes – wer mitten im Kampf das Spiel schließt, fällt.": "You can only abandon outside of combat – close the game mid-fight and you fall.",
  "Noch {n} Ruf bis {r}: {d}": "{n} more rep to {r}: {d}",
