  "ENDE DER WELT ERREICHT": "WORLD'S END REACHED",
  "Betreten: {n}": "Enter: {n}",
  "Ab Level {n} – dir fehlen noch {m}": "Requires level {n} – {m} to go",
  "Hinter dem Tor liegen die Endlosen Lande: eine Welt ohne Ende, für alle dieselbe – die beste Beute, aber wer dort stirbt, verliert, was er trägt.": "Beyond the gate lie the Endless Lands: a world without end, the same for everyone – the best loot, but if you die there, you lose what you carry.",
  "DIE ENDLOSEN LANDE": "THE ENDLESS LANDS",
  "Die beste Beute – aber wer dort stirbt, verliert, was er trägt.": "The best loot – but if you die there, you lose what you carry.",
  "{n} Dinge abgeholt": "{n} items collected",
  "Endlose Lande": "Endless Lands",
  "ab LV 5": "from LV 5",
  "Torhüterin Ysra": "Gatekeeper Ysra",
  "Hinter dem Tor liegen die Endlosen Lande. Wer dort fällt, kommt nackt zurück – wenn überhaupt.": "Beyond the gate lie the Endless Lands. Whoever falls there comes back stripped bare – if they come back at all.",
  "Nimm deinen Begleiter mit. Was in seiner Tasche steckt, bringt er immer heim.": "Take your companion along. Whatever's in its pouch, it always brings home.",
  "Je weiter du gehst, desto härter wird es. Ein Leuchtfeuer sichert den Weg, den du gegangen bist.": "The farther you go, the harder it gets. A beacon saves the path you've walked.",
  "Schluchten, Flüsse, Giftnebel … ohne das richtige Werkzeug kommst du nicht weiter. Die Kundschafterinnen wissen, wo eins liegt.": "Chasms, rivers, toxic fog … without the right tool, you won't get any further. The scouts know where to find one.",
  "Zwanzig Grenzen liegen zwischen hier und dem Rand. Hinter der elften helfen nur noch Meisterwerkzeuge – und am Ende der Welt wartet ein Denkmal auf den, der so weit kommt.": "Twenty barriers lie between here and the edge. Beyond the eleventh, only master tools will help you – and at World's End, a monument awaits whoever makes it that far.",
  "Spatz": "Sparrow",
  "Klein und flink – trägt 3 Dinge heim.": "Small and quick – carries 3 things home.",
  "Findet immer nach Hause – trägt 5 Dinge.": "Always finds its way home – carries 5 things.",
  "Rabe": "Raven",
  "Klug und kräftig – trägt 7 Dinge.": "Clever and strong – carries 7 things.",
  "Eule": "Owl",
  "Fliegt lautlos durch jede Nacht – trägt 9 Dinge.": "Flies silently through any night – carries 9 things.",
  "Phönixfeder": "Phoenix Feather",
  "Verglüht in einem Funkenregen und ersteht daheim neu – trägt 10 Dinge.": "Burns up in a shower of sparks and is reborn at home – carries 10 things.",
  "{bird} – trägt {n} Dinge heim": "{bird} – carries {n} things home",
  "{n} Plätze": "{n} slots",
  "Ab Voliere-Stufe {lv}": "From Aviary level {lv}",
  "Züchten": "Breed",
  "MAGISCHE VÖGEL": "MAGICAL BIRDS",
  "Sie bringen Beute aus den Endlosen Landen sofort heim – sicher, auch wenn du danach fällst.": "They fly loot home from the Endless Lands right away – safe, even if you fall afterwards.",
  "Hier einen Vogel züchten (oder in Truhen finden, bei Händler Bodo kaufen).": "Breed a bird here (or find one in chests, or buy one from Merchant Bodo).",
  "In den Landen: Rucksack öffnen → „Vogel schicken“.": "In the Lands: open your backpack → “Send Bird”.",
  "Dinge antippen – Gegenstände fliegen ins Lager, Gold und Material direkt zu dir. Nicht mitten im Kampf!": "Tap things – items fly to your stash, gold and materials straight to you. Not in the middle of a fight!",
  "ZÜCHTEN · VOLIERE STUFE {lv}": "BREEDING · AVIARY LEVEL {lv}",
  "Jede Stufe über der nötigen macht das Züchten 8 % billiger (bis 30 %).": "Each level above the required one makes breeding 8% cheaper (up to 30%).",
  "Brut: {p} % Chance auf einen zweiten Vogel.": "Brood: {p}% chance of a second bird.",
  "Ab Stufe 3 schlüpft manchmal ein zweiter Vogel.": "From level 3, a second bird sometimes hatches.",
  "Zwillinge! 2× {bird}": "Twins! 2× {bird}",
  "{bird} gezüchtet": "{bird} bred",
  "Nicht mitten im Kampf! Vögel fliegen nur, wenn dich gerade nichts angreift.": "Not in the middle of a fight! Birds only fly when nothing is attacking you.",
  "Du hast keinen solchen Vogel.": "You don't have that bird.",
  "Wähle zuerst etwas aus.": "Pick something first.",
  "So viel kann dieser Vogel nicht tragen.": "This bird can't carry that much.",
  "Vögel fliegen nur in den Endlosen Landen.": "Birds only fly in the Endless Lands.",
  "Keine Vögel dabei. Die Voliere im Versteck züchtet sie, Händler Bodo verkauft manchmal einen.": "No birds with you. The Aviary in your Hideout breeds them, and Merchant Bodo sometimes sells one.",
  "Im Kampf": "In combat",
  "Vogel schicken": "Send Bird",
  "Gegenstände fliegen ins Lager (ist es voll: in den Beutel, dann in die Fundkiste am Weltentor), Eier ins Brutnest, alles andere direkt zu dir.": "Items fly to your stash (if it's full: to your bag, then to the Lost & Found at the World Gate), eggs to the Hatchery, everything else straight to you.",
