  "Alles hat seinen Preis, {name}. Die Kunst ist, ihn vor den anderen zu kennen.": "Everything has its price, {name}. The trick is knowing it before everyone else.",
  "Kaspar bietet immer in der letzten Minute. Halt die Augen offen.": "Kaspar always bids at the last minute. Keep your eyes open.",
  "Wer versteigert, braucht Geduld. Wer bietet, braucht Nerven.": "Selling at auction takes patience. Bidding takes nerve.",
  "Ein Legendärer unter Marktwert? Kommt vor. Selten. Aber es kommt vor.": "A Legendary below market value? It happens. Rarely. But it happens.",
  "Grimbart sammelt alles, was glänzt – und zahlt dafür fast jeden Preis.": "Grimbart collects anything that glitters – and pays almost any price for it.",
  "Mein Hammer fällt, wenn die Zeit um ist. Keine Sekunde früher.": "My hammer falls when time's up. Not a second sooner.",
