  "Stufe {lv} · Geh zu einer Station und interagiere": "Level {lv} · Walk up to a station and interact",
  "Willkommen im Versteck, {name}. Noch ist es eine Ruine.": "Welcome to the Hideout, {name}. For now it's still a ruin.",
  "Die Gerüste dort? Dort bauen wir Schmiede, Labor, Schatzkammer und mehr. Geh hin und sieh, was es kostet.": "See the scaffolding? That's where we'll build the forge, the lab, the treasury and more. Go take a look at what it costs.",
  "Holz und Stein holst du dir am Rand des Verstecks: Hau auf die Bäume und Felsen ein. Und jeder Ausbau braucht seine Zeit – meine Leute sind fleißig, aber zaubern können sie nicht.": "You'll find wood and stone at the edge of the Hideout: just whack the trees and rocks. And every upgrade takes time – my crew works hard, but they can't do magic.",
  "Am Lagerfeuer kannst du einmal pro Akt rasten. Und das Portal bringt dich zurück zur Weltkarte.": "You can rest at the campfire once per act. And the portal takes you back to the world map.",
