  "Dauerhafter Bonus für alle Helden: {bonus}. Schlag die Trainingspuppe, um deinen Schaden pro Sekunde zu sehen.": "Permanent bonus for all heroes: {bonus}. Hit the Training Dummy to see your damage per second.",
  "+{n} % Schaden und LP": "+{n}% damage and HP",
  "Die Kumpel fördern für jeden geschafften Raum (bis zu 25).": "The miners dig for every room you clear (up to 25).",
