  "GESCHICHTE": "STORY",
  "BESTIARIUM": "BESTIARY",
  "Chronikseiten findest du in Truhen, bei Elite-Gegnern, Bossen und in Gräbern. Ab Bibliothek-Stufe 3 häufiger.": "You'll find chronicle pages in chests, on elite enemies and bosses, and in graves. More often from Library level 3.",
