  "SCHICKSALSTRUHEN": "FATE CHESTS",
  "Glücksmünzen gibt es von Bossen, Champions, seltenen Truhen, der Tages-Challenge und Schreinen Fortunas. Jede Drehung ist reiner Zufall mit den gezeigten Chancen – Mythisch kann beim ersten Dreh kommen oder erst nach sehr vielen.": "Fortune Coins come from bosses, champions, rare chests, the Daily Challenge and Fortuna's Shrines. Every spin is pure luck with the odds shown – Mythic can come on your first spin or only after a great many.",
  "Alle Kosmetik gesammelt – 4 Glücksmünzen zurück": "All cosmetics collected – 4 Fortune Coins back",
