  "Sofort fertig": "Finish now",
  "Beide Baumeister haben gerade nichts zu tun.": "Both master builders are idle right now.",
  "Der Baumeister hat gerade nichts zu tun. Ab Versteck-Stufe 50 hilft ein zweiter mit.": "The master builder is idle right now. From Hideout level 50, a second one lends a hand.",
  "Im Bau: {name}": "Building: {name}",
  "Ein Baumeister ist noch frei.": "One master builder is still free.",
  "kostenlos": "free",
  "SOFORT FERTIG?": "FINISH NOW?",
  "{name} wird sofort fertig und spart {t} Bauzeit.": "{name} finishes instantly, saving {t} of build time.",
  "Preis: {p}": "Price: {p}",
  "Ja, bezahlen": "Yes, pay",
  "Nicht genug Glücksmünzen": "Not enough Fortune Coins",
  "Fenrik näht größere Taschen – sie gelten für alle deine Helden.": "Fenrik sews bigger bags – they work for all your heroes.",
  "Beutel des Helden": "Hero's Bag",
  "Ausrüstung, die du mit dir trägst. Materialien, Edelsteine und Gold brauchen keinen Platz.": "Gear you carry with you. Materials, gems and gold take up no space.",
  "Rucksack in den Landen": "Backpack in the Lands",
  "Was du in den Endlosen Landen findest – bis du heimkehrst.": "What you find in the Endless Lands – until you return home.",
  "Begleiter-Tasche": "Companion Pouch",
  "Zusätzliche Plätze in der Tasche deines Begleiters.": "Extra slots in your companion's pouch.",
  "Ein guter Beutel ist wie ein guter Freund: Er trägt, ohne zu klagen.": "A good bag is like a good friend: it carries without complaining.",
  "Bring mir Leder und Pflanzenfaser, dann nähe ich dir Taschen, in die ein halber Drachenhort passt.": "Bring me leather and plant fiber, and I'll sew you bags that hold half a dragon's hoard.",
  "Gold und Edelsteine zählst du nur – aber Klingen und Rüstungen, die brauchen Platz.": "Gold and gems you just count – but blades and armor, those need space.",
  "Die Rucksäcke für die Lande nähe ich doppelt. Was dort reißt, ist für immer verloren.": "I double-stitch the backpacks for the Lands. Whatever tears out there is lost forever.",
  "Ein Vogel kennt immer den Weg nach Hause. Das ist mehr, als man von den meisten Helden sagen kann.": "A bird always knows the way home. That's more than you can say for most heroes.",
  "Federn, Holz und ein wenig Faser – mehr braucht ein Nest nicht. Und Geduld.": "Feathers, wood and a little fiber – that's all a nest needs. And patience.",
  "Raben sind klug. Zu klug. Zähl nach, was sie heimbringen.": "Ravens are clever. Too clever. Count what they bring home.",
  "Eine Phönixfeder verbrennt nie. Man sagt, sie fliegt sogar durch die Leere.": "A Phoenix Feather never burns out. They say it can even fly through the Void.",
  "Neu: Am Rand des Verstecks wachsen Bäume, Felsen und Büsche – hau drauf für Holz, Stein und Fasern. Jeder Ausbau braucht jetzt Bauzeit.": "New: trees, rocks and bushes grow at the edge of the Hideout – whack them for wood, stone and fiber. Every upgrade now takes build time.",
  "Tipp: Bäume, Felsen und Büsche kannst du mit Angriffen abbauen. Holz, Stein und Fasern brauchst du zum Bauen im Versteck.": "Tip: you can harvest trees, rocks and bushes with your attacks. You need wood, stone and fiber to build in the Hideout.",
  "ACKER · {n} BEETE": "FARM · {n} PLOTS",
  "Säe Samen und ernte in Echtzeit – das Feld wächst auch, während du unterwegs bist. Samen gibt es von Büschen, Kräutern und aus dem Garten.": "Sow seeds and harvest in real time – the field keeps growing while you're away. You get seeds from bushes, herbs and the garden.",
