  "SIEHE AUCH": "SEE ALSO",
  "KLINGENHORT": "KLINGENHORT",
  "Willkommen im Handbuch": "Welcome to the Handbook",
  "Hier steht alles über Klingenhort: jede Funktion, jeder Gegenstand, jedes Material. Tipp oben ein Wort ein – oder blättere links durch die Kapitel.": "Everything about Klingenhort is in here: every feature, every item, every material. Type a word at the top – or browse the chapters on the left.",
  "HÄUFIGE FRAGEN": "COMMON QUESTIONS",
  "KAPITEL": "CHAPTERS",
  "Nichts gefunden. Versuch ein anderes Wort – zum Beispiel „Holz“, „Schmiede“ oder „Drache“.": "Nothing found. Try another word – for example “wood”, “forge” or “dragon”.",
  "1 Treffer": "1 result",
  "{n} Treffer": "{n} results",
