  "Handbuch": "Handbook",
  "Wo finde ich {mat}?": "Where do I find {mat}?",
  "häufig": "common",
  "selten": "rare",
  "sehr selten": "very rare",
  "Bäume in den Endlosen Landen": "Trees in the Endless Lands",
  "2–4 Holz je Baum – je weiter draußen, desto mehr (bis zu dreimal so viel). Kakteen und Knochenbäume geben manchmal 1, Sternenbäume 1–2.": "2–4 wood per tree – the farther out, the more (up to three times as much). Cacti and bone trees sometimes give 1, star trees 1–2.",
  "Felsen und Steine in den Endlosen Landen": "Rocks and stones in the Endless Lands",
  "Große Felsen geben 3–5 Stein, kleine Steine 1–3 – tief draußen mehr. Auch Säulen, Kristalle und Korallen geben etwas.": "Big rocks give 3–5 stone, small stones 1–3 – more the deeper you go. Pillars, crystals and corals give some too.",
  "Büsche, Pilze und Kakteen": "Bushes, mushrooms and cacti",
  "Büsche geben 1–2 Fasern, Pilze und Kakteen 2–3, Riesenpilze doppelt so viel. Kräuterbeete in den Landen manchmal 1.": "Bushes give 1–2 fiber, mushrooms and cacti 2–3, giant mushrooms twice as much. Herb patches in the Lands sometimes give 1.",
  "Büsche, Pilze, Bäume und Kräuterbeete": "Bushes, mushrooms, trees and herb patches",
  "Büsche (45 %), Pilze (50 %) und Bäume (12 %) lassen manchmal einen Samen fallen. Kräuterbeete in den Landen geben immer 1–2, Vogelnester manchmal einen.": "Bushes (45%), mushrooms (50%) and trees (12%) sometimes drop a seed. Herb patches in the Lands always give 1–2, bird nests sometimes one.",
  "Vogelnester in den Bäumen der Lande": "Bird nests in the trees of the Lands",
  "Etwa jeder 40. Baum trägt ein Nest. Beim ersten Treffer fällt es herunter: 2–4 Federn, weit draußen eine mehr. Büsche geben selten eine Feder.": "About every 40th tree has a nest. It falls down on the first hit: 2–4 feathers, one more far out. Bushes rarely give a feather.",
  "Bäume tiefer in den Landen": "Trees deeper in the Lands",
  "Ab Stufe 13 (etwa {km} vom Weltentor) gibt jeder Baum manchmal 1–2 Eisenholz. Je tiefer, desto öfter – bis fast jeder zweite Baum.": "From tier 13 (about {km} from the World Gate), any tree sometimes gives 1–2 Ironwood. The deeper you go, the more often – up to almost every second tree.",
  "Alte und dunkle Wälder: hier am meisten": "Old and dark forests: the most here",
  "In diesen Biomen gibt es viel mehr Eisenholz: {list}.": "These biomes have much more Ironwood: {list}.",
  "Weltenbäume: immer": "World Trees: always",
  "Ein riesiger Weltenbaum gibt immer Eisenholz – gleich 3–6 Stück. Du findest sie als Wahrzeichen mancher Regionen und im {list}.": "A giant World Tree always gives Ironwood – 3–6 pieces at once. You'll find them as landmarks in some regions and in the {list}.",
  "Bäume weit draußen": "Trees far out",
  "Ab Stufe 55 (etwa {km} vom Weltentor) geben Bäume manchmal Sternholz – viel öfter in: {list}.": "From tier 55 (about {km} from the World Gate), trees sometimes give Starwood – much more often in: {list}.",
  "Sternen- und Glasbäume": "Star trees and glass trees",
  "Geben immer 1–2 Sternholz. Sie wachsen in: {list}.": "Always give 1–2 Starwood. They grow in: {list}.",
  "Felsen tiefer in den Landen": "Rocks deeper in the Lands",
  "Ab Stufe 16 (etwa {km} vom Weltentor) geben Felsen und Steine manchmal Marmor.": "From tier 16 (about {km} from the World Gate), rocks and stones sometimes give Marble.",
  "Helle Felsen": "Pale rocks",
  "Hier gibt fast jeder Fels Marmor: {list}.": "Almost every rock here gives Marble: {list}.",
  "Alte Säulen": "Ancient pillars",
  "Säulen geben 2–4 Marmor: {list}. Kristalle und Korallen manchmal einen.": "Pillars give 2–4 Marble: {list}. Crystals and corals sometimes give one.",
  "Felsen weit draußen": "Rocks far out",
  "Ab Stufe 36 (etwa {km} vom Weltentor) geben Felsen manchmal Obsidian.": "From tier 36 (about {km} from the World Gate), rocks sometimes give Obsidian.",
  "Dunkle Felsen": "Dark rocks",
  "Hier gibt etwa jeder zweite Fels Obsidian: {list}.": "About every second rock here gives Obsidian: {list}.",
  "Obsidianfelsen": "Obsidian rocks",
  "Geben immer 1–3 Obsidian: {list}.": "Always give 1–3 Obsidian: {list}.",
  "Knochenbäume und Riesenschädel": "Bone trees and giant skulls",
  "Geben 2–3 Knochenstaub: {list}.": "Give 2–3 Bone Dust: {list}.",
  "Leuchtende Kristalle": "Glowing crystals",
  "Kristalle in den Landen geben manchmal einen Seelenkristall: {list}.": "Crystals in the Lands sometimes give a Soul Crystal: {list}.",
  "Schrott und große Felsen": "Scrap and big rocks",
  "Rostiger Schrott gibt 2–3 Eisenerz ({list}), große Felsen manchmal 1–2.": "Rusty scrap gives 2–3 Iron Ore ({list}), big rocks sometimes 1–2.",
  "Schrott weit draußen": "Scrap far out",
  "Ab Stufe 14 gibt Schrott manchmal Mithrilerz: {list}.": "From tier 14, scrap sometimes gives Mithril Ore: {list}.",
