  "Auftrag erfüllt: {q} – hol dir die Belohnung an der Auftragstafel!": "Quest complete: {q} – claim your reward at the Quest Board!",
  "ABGEHOLT": "CLAIMED",
  "Belohnung abholen": "Claim reward",
  "Neu würfeln (gratis)": "Reroll (free)",
  "Ruf-Marken": "Rep Tokens",
  "{n} Tagen": "{n} days",
  "Alles abholen ({n})": "Claim all ({n})",
  "NOCH ABZUHOLEN": "READY TO CLAIM",
  "HEUTE": "TODAY",
  "Neue Aufträge in {t}": "New quests in {t}",
  "Heute gibt es nichts für dich zu tun.": "Nothing for you to do today.",
  "Einmal am Tag darfst du einen Tagesauftrag gratis neu würfeln.": "Once a day you can reroll a daily quest for free.",
  "Heute hast du schon neu gewürfelt.": "You've already rerolled today.",
  "DIESE WOCHE": "THIS WEEK",
  "Jeder Auftrag gehört zu einer Fraktion: Abholen bringt Ruf und Ruf-Marken. Mit Ruf steigst du im Rang (Vorteile), mit Marken tauschst du beim Quartiermeister.": "Every quest belongs to a faction: claiming it earns reputation and Rep Tokens. Reputation raises your rank (perks), and tokens can be traded at the Quartermaster.",
  "Rang {n}: {rank}": "Rank {n}: {rank}",
  "Rang {n} von {m}: {rank}": "Rank {n} of {m}: {rank}",
  "{a} / {b} RUF": "{a} / {b} REP",
  "HÖCHSTER RANG · {a} RUF": "MAX RANK · {a} REP",
  "Elwas Aufträge in den Landen zählen hier mit.": "Elwa's missions in the Lands count here too.",
  "Nächster Rang „{rank}“: {d}": "Next rank “{rank}”: {d}",
  "VORTEILE JETZT": "CURRENT PERKS",
  "Noch keine – der erste Rang bringt den ersten Vorteil.": "None yet – your first rank brings your first perk.",
  "RANG {n} · {rank}": "RANK {n} · {rank}",
  "Zum Quartiermeister": "To the Quartermaster",
  "DEIN TITEL": "YOUR TITLE",
  "Kein Titel": "No title",
  "Tippe eine Fraktion an: Ränge, Vorteile und was als Nächstes kommt.": "Tap a faction: ranks, perks and what comes next.",
  "Vier Fraktionen. Ruf bringt Ränge mit kleinen, dauerhaften Vorteilen für alle deine Helden.": "Four factions. Reputation earns ranks with small, permanent perks for all your heroes.",
  "ab Rang {n} „{rank}“": "from rank {n} “{rank}”",
  "noch {n} diese Woche": "{n} left this week",
  "diese Woche ausverkauft": "sold out this week",
  "Kommt in dein Brutnest.": "Goes into your Hatchery.",
  "Erscheint bei deinem Helden.": "Shown with your hero.",
  "{fk}: Du hast {n} Ruf-Marken, dein Rang ist {r} – {rank}.": "{fk}: You have {n} Rep Tokens, your rank is {r} – {rank}.",
  "Tauschangebote dieser Woche – neue in {t}. Bezahlt wird mit Ruf-Marken und Gold.": "This week's trade offers – new ones in {t}. You pay with Rep Tokens and gold.",
  "AUFTRAGSTAFEL": "QUEST BOARD",
  "FRAKTIONEN": "FACTIONS",
  "NEUER RANG!": "NEW RANK!",
  "AUFTRAG ERFÜLLT!": "QUEST COMPLETE!",
  "{n} AUFTRÄGE ERFÜLLT!": "{n} QUESTS COMPLETE!",
  "Alle Belohnungen auf einen Blick:": "All rewards at a glance:",
  "Neuer Auftrag: {q}": "New quest: {q}",
  "Getauscht: {item}": "Traded: {item}",
  "Auftragstafel": "Quest Board",
  "Tages- und Wochenaufträge, Ruf bei den Fraktionen und ihre Tauschangebote.": "Daily and weekly quests, reputation with the factions and their trade offers.",
  "Hier hängen deine Tages- und Wochenaufträge. Abholen bringt Gold, Material und Ruf bei einer der vier Fraktionen – und Ruf-Marken für ihre Tauschangebote.": "Your daily and weekly quests are posted here. Claiming them earns gold, materials and reputation with one of the four factions – plus Rep Tokens for their trade offers.",
  "Zur Auftragstafel": "To the Quest Board",
  "Aufträge und Ruf": "Quests and Reputation",
  "Tages- und Wochenaufträge, Fraktionen, Ruf-Marken": "Daily and weekly quests, factions, Rep Tokens",
  "Jeden Tag drei neue Aufträge, jede Woche drei größere – mit Gold, Material und Ruf als Belohnung.": "Three new quests every day, three bigger ones every week – with gold, materials and reputation as rewards.",
  "Die Auftragstafel steht im Versteck zwischen Bibliothek und Lagerfeuer. Auf der Weltkarte findest du sie unter „Mehr“ → „Aufträge & Ruf“.": "The Quest Board stands in your Hideout between the Library and the Campfire. On the World Map you'll find it under “More” → “Quests & Rep”.",
  "Tagesaufträge gibt es um Mitternacht neu, Wochenaufträge am Montag. Jeder Held hat seine eigenen.": "Daily quests refresh at midnight, weekly quests on Monday. Each hero has their own.",
  "Die Ziele wachsen mit deinem Level. Es kommen nur Aufträge, die du gerade schaffen kannst – die Endlosen Lande zum Beispiel erst ab Level 5.": "Goals grow with your level. You only get quests you can actually do right now – the Endless Lands, for example, only from level 5.",
  "Ist ein Auftrag erfüllt, bekommst du sofort eine Meldung. Abholen musst du ihn an der Tafel. Erfüllte Aufträge verfallen nicht – sie warten unter „Noch abzuholen“.": "When a quest is complete, you get a message right away. You claim it at the board. Completed quests never expire – they wait under “Ready to claim”.",
  "Belohnung: Gold, manchmal Glücksmünzen, Material (auch Holz, Eisenholz, Marmor …), Bauteile, ab und zu ein Mod oder ein Ei – dazu Ruf und Ruf-Marken. Wochenaufträge bringen etwa fünfmal so viel.": "Rewards: gold, sometimes Fortune Coins, materials (including Wood, Ironwood, Marble …), parts, now and then a mod or an egg – plus reputation and Rep Tokens. Weekly quests give about five times as much.",
  "Alle Auftragsarten": "All quest types",
  "Was eine Fraktion von dir will – Beispiele für dein Level.": "What each faction wants from you – examples for your level.",
  "Tag und Woche · Woche: {t}": "Daily and weekly · Weekly: {t}",
  "Wochenauftrag": "Weekly quest",
  "Tagesauftrag": "Daily quest",
  "für dich gerade noch nicht dabei": "not available to you yet",
  "Die Zahlen passen zu deinem Level – höhere Level bekommen größere Ziele und mehr Belohnung.": "The numbers match your level – higher levels get bigger goals and bigger rewards.",
  "Fraktionen, Ruf und Ränge": "Factions, reputation and ranks",
  "Vier Fraktionen – jeder Auftrag bringt Ruf bei einer von ihnen.": "Four factions – every quest earns reputation with one of them.",
  "{n} Ränge · {s}": "{n} ranks · {s}",
  "Ruf bekommst du für Aufträge der Fraktion. Bei den Kundschaftern zählen auch Elwas Aufträge in den Landen.": "You earn reputation from a faction's quests. For the Scouts, Elwa's missions in the Lands count too.",
  "Mit genug Ruf steigst du im Rang. Jeder Rang bringt einen kleinen, dauerhaften Vorteil – für alle deine Helden.": "With enough reputation you rank up. Every rank brings a small, permanent perk – for all your heroes.",
  "Ruf geht nie verloren.": "Reputation is never lost.",
  "Ruf-Marken und Quartiermeister": "Rep Tokens and Quartermaster",
  "Jede Fraktion zahlt mit eigenen Marken – getauscht wird an der Auftragstafel unter „TAUSCH“.": "Each faction pays in its own tokens – trade them at the Quest Board under “TRADE”.",
  "Für jeden Auftrag gibt es Ruf-Marken seiner Fraktion: 2 bis 3 für einen Tagesauftrag, 8 bis 10 für einen Wochenauftrag.": "Every quest gives Rep Tokens of its faction: 2 to 3 for a daily quest, 8 to 10 for a weekly quest.",
  "Jede Woche hat jede Fraktion fünf andere Tauschangebote. Bezahlt wird mit Ruf-Marken und etwas Gold.": "Every week each faction has five different trade offers. You pay with Rep Tokens and a bit of gold.",
  "Bessere Angebote gibt es erst ab einem bestimmten Rang: seltene Eier, Mods, seltene Rohstoffe, Leuchtfeuersteine, magische Vögel – und ganz oben ein Titel für deinen Helden.": "Better offers only unlock at certain ranks: rare eggs, mods, rare resources, beacon stones, magic birds – and at the very top, a title for your hero.",
  "Jedes Angebot gibt es nur ein paarmal pro Woche.": "Each offer is only available a few times per week.",
  "spricht für die Fraktion.": "speaks for the faction.",
  "DEIN RANG": "YOUR RANK",
  "RUF": "REP",
